sys_script.script:
(function() {
    var ref = current.getValue('customer_reference');
    if (ref && ref.trim() !== '') return;
    var maxNum = 1000;
    var gr = new GlideRecord('x_2056099_indust_0_cust_order');
    gr.addQuery('customer_reference', 'STARTSWITH', 'PO-REF-');
    gr.orderByDesc('customer_reference');
    gr.setLimit(1);
    gr.query();
    if (gr.next()) {
        var parts = gr.getValue('customer_reference').split('-');
        var last = parseInt(parts[2], 10);
        if (!isNaN(last) && last >= maxNum) maxNum = last;
    }
    var candidate = maxNum + 1;
    var check = new GlideRecord('x_2056099_indust_0_cust_order');
    check.addQuery('customer_reference', 'PO-REF-' + candidate);
    check.setLimit(1);
    check.query();
    while (check.hasNext()) {
        candidate++;
        check = new GlideRecord('x_2056099_indust_0_cust_order');
        check.addQuery('customer_reference', 'PO-REF-' + candidate);
        check.setLimit(1);
        check.query();
    }
    current.setValue('customer_reference', 'PO-REF-' + candidate);
})()
